Open Scope Z_scope.

Module EVBRU.
Import PMES.
Import EVNB.
Import EVBB.
Module G := GR.
Module GT := GRT.
Abbreviation mem := (word -> option byte).
Definition uv := PB.uv.

Section Root.
Context {SCFG_P : ScfgP}.
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis LAY : PmLayout.pm0_layout L.
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps RSEGS (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom RSEGS)) -> PML.fp_ok fx -> PML.fp_ok fx'.
Hypothesis TRUE_OK : true_literal_spec L.
Hypothesis FALSE_OK : false_literal_spec L.
Hypothesis APPEND_OK : str_append_x_specU L HI.

Section Stretch.
Variables (E0 : env) (sp V S2 : Z).
Hypothesis U2 : bv_unsigned (ev E0 2) = sp.
Hypothesis U10 : bv_unsigned (ev E0 10) = V.
Hypothesis SPR : hl_ceil L + 10624 <= sp /\ sp <= hl_sptop L /\ 0x7fff80000000 <= hl_sptop L <= 2 ^ 47.
Hypothesis OBJS : objs_enc L sp V S2.

Lemma LIT_OK : forall f, literal_spec L (PCf f) (LSf f) (LGf f) (LTXTf f) (LLENf f).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$f;R+0-0RN$b;R+0!7'1/SCFG_P;/L;!1'2#1!1'3#1!1'4#1!1'5#1!1'6#1#12/TRUE_OK;/FALSE_OK;").
Qed.

