Lemma lits_stretch : forall (F : list SGP.region) E' (M M' : mem), SP.F_sub F F0R = true -> env_agree GT.NF E0 E' ->
  (forall a : word, SGP.outside E' F a -> M' a = M a) -> forall a, PML.LIT_LO <= a < PML.LIT_HI -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a).
Proof using OBJS SPR U10 U2. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S^F0|600;!1,R0!1+_:1|30;!1+_;!1+_:!1,R3%~R24!4'Z/L;/sp;/V;'[!1,G|48;!2+B!4'Z/L;/sp;/S2;7!4'\/V;'[/S2;7!2'C/sp;/V;!1'^0/L;!2'C!2'J/V;'[:!3+<+;!2'^1/V;!1,G3,D!2+B;<!1,G|G000000;!1,G|=0980;!2'C!2'J!2'I:>?/sp;!2'C/sp;:!1,G|^13fff80000000;|10;!1,GC!1,G|50f;!2'FDE!2'C:F!2+B!2'CB:G!2+BAH!2'S1#H!2'^:DE!2'E,DD%~RL%~R!2'C,DE!2'E,DF!2'C,DD$Ha;RN$~R+^;!3'^<DE#2%Ha;RN%~R+^;!2'C,DF!1,G0!2'FDQ!1,^=+^>!1+8+^>!1+^B+;!1+^D+;!1,G|C5b5c8;!2,^M+;,^Q!1,G|C5b610;!2,^O+;Y!1,^T+^F!2'^VV,^G!4'^W#1#3vv!2,^X+0,?!3+<+0!2'^Y#1#3,?!3'^Z+;,D#2}3}2}1!3,_F+;!2,_G+;^1!3,_F+;!2,_G+;^2!3,_F+;!2,_G+;^3!2,_G+;,_H!1,^A+;!2,^@+;#4|22;!2,^M+;^7!7,^JV'^E+^F+^F,^G!4,^K+;!2,^O+;B,^P^8,^R!2,^O+;?!3,^L+;!3,^L+;^8!2,^N+;!2,^O+;>^:!6,_KV'^E+^F+^F,^G#7!2,^M+;C!7,^JV'^E+^F+^F,^G!4,^K+;^=,^SZ,^R!6,_KV'^E+^F+^F,^G#8!1'^[>!2'CW#K|20;!2,^M+;^B!1,G|828;!2'S1#?$F;R!1+8'9$E';R+:$M;R5$M';R5$HF;R!3+<+0!2'=#4'>,?$Hag;R!3'@'A/E0;#4$HFR;R%a;R2%~R!3'_9#6#7#1!3+<4!1#5#2!1#6#2$a;R+;$Ha;R!2+B!2'C'`W#1!2'E#1'`X&o;R/OBJS;!2+B68!5'K68!3+<4!1#7!2'S1#3!1#8!2'S1#3$~R6$~R8!2$H;R6!5'K9=%~R8!3+<4!1#;!2'S1#7!1#<!2'S1#7$~R9$~R=!2$A1;R9$H;R=!5'K;<%~R8!3+<4!1#?!2'S1#;!1#@!2'S1#;$~R;$~R<!2$A2;R;$A3;R<$_H;R8vd&a0;R/SPR;!2+B@I!5'K@I!3+<4!1#D!2'S1#@!1#E!2'S1#@$~R@$~RI!2$P1;R@$H;RI!5'KAH!3+<4!1#H!2'S1#D!1#I!2'S1#D$~RA$~RH!2$P2;RA$P3;RHvd!2#IJ!8'_C#O#N#H#K#J&__sat14;RKM&__sat13;ROP&__sat12;R!2'^:DQ%~RL%~R!2'C,DQ!2'E,DR&__sat11;R$Ha;RN$~R+^;!3'^<DQ#2%Ha;RN%~R+^;!2'C,DR&__arith;R$__x1;R+;&__wit;RST&__varmap;R!2,^@+;#2U&__ff;R!8,^CV'^E+^F+^F,^G!7,^IV'^E+^F+^F,^G!7,^JV'^E+^F+^F,^G!4,^K+;!2,^O+;W,^PX,^R!7,^JV'^E+^F+^F,^G!4,^K+;X,^SZ,^R[!7,^IV'^E+^F+^F,^G!7,^JV'^E+^F+^F,^G!4,^K+;!2,^O+;,D,^PX,^R!7,^JV'^E+^F+^F,^G!4,^K+;X,^S!3,_0+;!2,^O+;D1,^R\^0%__x1;R+;%~R!2+B!2'CW#1!2'E#1Y!2+B!2'C,D#2!2'E#2R!2#1#M#L&__sat12;RKM&__sat11;ROP&__arith;R$__p3;Rw$__p2;Rw$__p1;Rw$__x3;R+;$__x2;R+;$__x1;R+;&__wit;R!3,_D+^>!2,_E^4,_IST&__varmap;R!4,^?+;!4,^?+;^5#3^6#2^5U&__ff;R!8,^CV'^E+^F+^F,^G!7,^IV'^E+^F+^F,^G^9!6,_